import { useEffect, useMemo, useState, type Ref } from "react";
import { resolveTheme, usePreferencesStore } from "../stores/preferences";

/**
 * Renders an agent-authored HTML/CSS/JS prototype in a hardened sandbox.
 *
 * Threat model: the `html` is generated by the agent, so it's untrusted code.
 * Two independent layers contain it:
 *
 *  1) `sandbox="allow-scripts"` WITHOUT `allow-same-origin` → the iframe runs at
 *     a unique OPAQUE origin. Scripts execute, but they cannot reach the parent
 *     DOM, read the daemon's cookies / localStorage, or make same-origin
 *     (credentialed) requests. This is the hard isolation.
 *  2) A locked-down CSP injected into the document: `default-src 'none'` with no
 *     `connect-src` blocks ALL network egress (fetch / XHR / WebSocket / beacon),
 *     so a prototype can't phone home or pull in third-party resources. Inline
 *     style/script are allowed so a self-contained prototype actually runs;
 *     `form-action 'none'` and `base-uri 'none'` close the obvious side doors.
 *
 * On top of that: a hard SIZE CAP, and CLICK-TO-RUN so agent code never executes
 * until the human opts in (and sees the "sandboxed · no network" banner first).
 */
const MAX_HTML_BYTES = 512 * 1024;

/** Human-readable cap for the too-large notice (KB below 1 MB, else MB). */
function formatCap(bytes: number): string {
  return bytes >= 1024 * 1024 ? `${Math.round((bytes / (1024 * 1024)) * 10) / 10} MB` : `${Math.round(bytes / 1024)} KB`;
}

/** Does the page carry anything a script-less frame would hold back? */
function hasScripts(html: string): boolean {
  return /<script\b|\son[a-z]+\s*=|javascript:/i.test(html);
}

/** The injected CSP. `script-src` is `'unsafe-inline'` once the human has
 *  chosen Run (agent scripts run), or a per-render NONCE before Run (#680 slice
 *  2: only our annotator's script tag carries it, so no agent markup can
 *  execute even if the sanitiser missed something). */
function buildCsp(scriptSrc: string): string {
  return [
    "default-src 'none'",
    "img-src data: blob:",
    "style-src 'unsafe-inline'",
    "font-src data:",
    `script-src ${scriptSrc}`,
    "form-action 'none'",
    "base-uri 'none'",
  ].join("; ");
}

/** A fresh nonce for the before-Run CSP. */
function makeNonce(): string {
  const bytes = new Uint8Array(16);
  const c = (globalThis as { crypto?: Crypto }).crypto;
  if (c?.getRandomValues) c.getRandomValues(bytes);
  else for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(Math.random() * 256);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
}

/** Attribute-value escaping for the wrapper's own `<html>`/`<body>` tags. */
function escapeAttr(v: string): string {
  return v.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
/** Only these names are ever written onto the wrapper (the sanitiser already
 *  filtered the values; this is the second gate on the names). */
const WRAPPER_ATTR_NAMES = new Set(["class", "dir", "lang", "style"]);
function attrString(attrs: Record<string, string> | undefined): string {
  if (!attrs) return "";
  return Object.entries(attrs)
    .filter(([k]) => WRAPPER_ATTR_NAMES.has(k))
    .map(([k, v]) => ` ${k}="${escapeAttr(v)}"`)
    .join("");
}

export function wrapHtml(
  html: string,
  opts: { headScript?: string; nonce?: string; htmlAttrs?: Record<string, string>; bodyAttrs?: Record<string, string> } = {},
): string {
  // Wrap the agent payload in a document we control so OUR CSP meta is first in
  // <head> and governs the whole document (it combines with anything the agent
  // included — most restrictive wins). The sandbox attribute is the primary
  // defense regardless; this is defense-in-depth against network egress.
  // #680 slice 2 — an optional head script (the page annotator) goes right
  // after the CSP, before any agent markup, so it is the first script to run.
  const csp = buildCsp(opts.nonce ? `'nonce-${opts.nonce}'` : "'unsafe-inline'");
  const head = opts.headScript
    ? `<script${opts.nonce ? ` nonce="${opts.nonce}"` : ""}>${opts.headScript}</script>`
    : "";
  return (
    `<!doctype html><html${attrString(opts.htmlAttrs)}><head><meta charset="utf-8">` +
    `<meta http-equiv="Content-Security-Policy" content="${csp}">` +
    head +
    `<style>html,body{margin:0;padding:10px;font-family:system-ui,-apple-system,sans-serif;color:#111;background:#fff}</style>` +
    `</head><body${attrString(opts.bodyAttrs)}>${html}</body></html>`
  );
}

/** #680 slice 2 — page annotation: the annotator script (inlined first in the
 *  frame) and the before-Run sanitiser. Passed in by the page renderer so this
 *  component, which prototype visuals also use, carries neither by default. */
export interface FrameAnnotation {
  script: string;
  /** Returns the cleaned markup plus the page's safe `<html>`/`<body>`
   *  presentation attributes, which go on our wrapper elements. */
  sanitize: (html: string) => { html: string; htmlAttrs?: Record<string, string>; bodyAttrs?: Record<string, string> };
  /** #714 gap 11 — an async parent-side pass over the agent HTML before the
   *  srcdoc is built (Mermaid blocks rendered to sanitized SVG). `needed` is a
   *  cheap synchronous gate; `run` never rejects and resolves to the HTML to
   *  frame (both the before-Run and the Run document use it). */
  prepare?: FramePrepare;
}

export interface FramePrepare {
  needed: (html: string) => boolean;
  run: (html: string, theme: "light" | "dark") => Promise<string>;
}

export interface PrototypeFrameProps {
  html: string;
  staticPreview?: boolean;
  /** Size cap in bytes. Defaults to 512 KB (prototype visuals); the #680 page
   *  artifact passes PAGE_HTML_MAX_BYTES (2 MB). */
  maxBytes?: number;
  /** #680 — render the page BEFORE Run in a script-less frame (`sandbox=""`:
   *  opaque origin, no scripts at all), so markup and CSS are readable at once.
   *  Run then remounts the frame with `allow-scripts`. Without it (prototype
   *  visuals) nothing renders until Run, as before. */
  staticFirst?: boolean;
  /** Noun used in the copy ("prototype" / "page"). */
  noun?: string;
  /** Classes for the live iframe (height). */
  frameClassName?: string;
  /** #680 slice 2 — annotate the page. Before Run the frame gets
   *  `allow-scripts` but only the sanitised markup plus our annotator (nonce
   *  CSP); after Run, the full agent HTML plus the annotator. Still never
   *  `allow-same-origin`, still no network. Requires `staticFirst`. */
  annotation?: FrameAnnotation;
  /** The live iframe element (to match `event.source` and post to it). */
  iframeRef?: Ref<HTMLIFrameElement>;
  /** Told when the human chooses Run (the frame remounts). */
  onRunningChange?: (running: boolean) => void;
}

export function PrototypeFrame({
  html,
  staticPreview = false,
  maxBytes = MAX_HTML_BYTES,
  staticFirst = false,
  noun = "prototype",
  frameClassName = "w-full h-[420px] rounded border border-border-default bg-white",
  annotation,
  iframeRef,
  onRunningChange,
}: PrototypeFrameProps) {
  const [running, setRunning] = useState(false);
  const [showSource, setShowSource] = useState(false);

  const size = new Blob([html]).size;
  const tooBig = size > maxBytes;
  const scripted = staticFirst && hasScripts(html);
  const annotating = staticFirst && !!annotation;

  // #714 gap 11 — render the page's Mermaid blocks in the parent before the
  // frame gets its srcdoc. Until the first result for this HTML lands, a
  // placeholder stands in (so the frame loads once, not twice); a theme flip
  // keeps the current frame up until the re-themed render is ready. Once the
  // human has chosen Run the theme is pinned to the one at Run, so a theme
  // flip never reloads a running page (it re-themes on the next mount).
  // Run also FREEZES the prepared document on screen at that moment: a render
  // still in flight (say, for a theme flipped just before Run) may resolve
  // later, but it only updates `prepared` (the before-Run document), never the
  // running frame's srcdoc, which would reload the page and re-run its
  // scripts. The frozen copy is keyed to `html`: a new page while running is
  // prepared afresh (in the pinned run theme) and frames once ready.
  const appTheme = resolveTheme(usePreferencesStore((s) => s.theme));
  const [runTheme, setRunTheme] = useState<"light" | "dark" | null>(null);
  const theme = running && runTheme ? runTheme : appTheme;
  const prepare = annotation?.prepare;
  // `needed` may parse the page (a DOMParser pass), so once per html.
  const prepNeeded = useMemo(
    () => !!(staticFirst && !tooBig && prepare?.needed(html)),
    [staticFirst, tooBig, prepare, html],
  );
  const prep = prepNeeded && prepare ? prepare : null;
  const [prepared, setPrepared] = useState<{ html: string; out: string } | null>(null);
  useEffect(() => {
    if (!prep) return;
    let live = true;
    prep.run(html, theme).then(
      (out) => { if (live) setPrepared({ html, out }); },
      () => { if (live) setPrepared({ html, out: html }); },
    );
    return () => { live = false; };
  }, [prep, html, theme]);
  const preparedHtml: string | null = prep ? (prepared?.html === html ? prepared.out : null) : html;
  const [runFrozen, setRunFrozen] = useState<{ html: string; out: string } | null>(null);
  const frameHtml: string | null = running && runFrozen?.html === html ? runFrozen.out : preparedHtml;
  const startRun = () => {
    setRunTheme(appTheme);
    setRunFrozen(preparedHtml !== null ? { html, out: preparedHtml } : null);
    setRunning(true);
  };

  useEffect(() => {
    onRunningChange?.(running);
  }, [running, onRunningChange]);

  // #680 slice 2 — the before-Run document: sanitised agent markup, our
  // annotator first, and a nonce CSP so only the annotator can run. Memoized
  // so a re-render doesn't hand the iframe a new srcdoc (which would reload it).
  const staticDoc = useMemo(() => {
    if (!staticFirst || tooBig || preparedHtml === null) return "";
    if (!annotation) return wrapHtml(preparedHtml);
    const clean = annotation.sanitize(preparedHtml);
    return wrapHtml(clean.html, {
      headScript: annotation.script,
      nonce: makeNonce(),
      htmlAttrs: clean.htmlAttrs,
      bodyAttrs: clean.bodyAttrs,
    });
  }, [preparedHtml, staticFirst, tooBig, annotation]);
  const runDoc = useMemo(
    () =>
      running && frameHtml !== null
        ? wrapHtml(frameHtml, annotating && annotation ? { headScript: annotation.script } : {})
        : "",
    [frameHtml, running, annotating, annotation],
  );

  if (!html.trim()) {
    return <div className="text-2xs text-text-muted">No {noun} HTML provided.</div>;
  }

  return (
    <div className="space-y-1.5">
      <div className="flex items-center gap-2 text-[10px] text-text-muted">
        <span className="px-1.5 py-0.5 rounded bg-surface-elevated">🔒 sandboxed · no network</span>
        <span>Agent-generated — runs in an isolated frame.</span>
      </div>

      {tooBig ? (
        <div className="text-2xs text-accent-amber rounded border border-dashed border-border-default p-3 text-center">
          {noun === "prototype" ? "Prototype" : `This ${noun}`} is too large to render safely ({Math.round(size / 1024)} KB &gt; {formatCap(maxBytes)} cap).
        </div>
      ) : staticPreview ? (
        // Static preview (e.g. revision diff): don't offer to run it here (it
        // would render a second live frame side-by-side). Source is still
        // viewable below. Note: this is SEPARATE from comment-anchoring
        // read-only — a live per-option prototype is not staticPreview.
        <div className="w-full rounded border border-dashed border-border-default bg-surface-elevated p-3 text-center text-2xs text-text-muted">
          Prototype (preview) — open the live version to run it.
        </div>
      ) : frameHtml === null ? (
        <div
          className={`${frameClassName} flex items-center justify-center text-2xs text-text-muted`}
          data-testid="frame-diagrams-rendering"
          role="status"
        >
          Rendering diagrams…
        </div>
      ) : running ? (
        <iframe
          // No `allow-same-origin` — opaque origin, no parent/cookie/storage access.
          ref={iframeRef}
          sandbox="allow-scripts"
          srcDoc={runDoc}
          title={`Sandboxed ${noun}`}
          className={frameClassName}
        />
      ) : staticFirst ? (
        // #680 — the page is readable before Run: an EMPTY sandbox token list
        // means no scripts, no forms, no popups, opaque origin. Agent scripts
        // stay inert until the human opts in below.
        <div className="space-y-1.5">
          <iframe
            ref={iframeRef}
            // #680 slice 2 — when annotating, `allow-scripts` so the annotator
            // runs; the agent's scripts were stripped and the nonce CSP stops
            // anything else. Never `allow-same-origin` in either mode.
            sandbox={annotating ? "allow-scripts" : ""}
            srcDoc={staticDoc}
            title={`Sandboxed ${noun} (scripts paused)`}
            className={frameClassName}
          />
          {scripted && (
            <button
              onClick={startRun}
              className="w-full rounded border border-dashed border-accent-violet/40 bg-accent-violet-dim/15 p-2 text-center
                         text-xs text-accent-violet hover:bg-accent-violet-dim/25 transition-colors"
            >
              ▶ Run {noun} scripts (sandboxed)
            </button>
          )}
        </div>
      ) : (
        <button
          onClick={startRun}
          className="w-full rounded border border-dashed border-accent-violet/40 bg-accent-violet-dim/15 p-4 text-center
                     text-xs text-accent-violet hover:bg-accent-violet-dim/25 transition-colors"
        >
          ▶ Run prototype (sandboxed)
        </button>
      )}

      <button
        onClick={() => setShowSource((s) => !s)}
        className="text-[10px] text-text-muted hover:text-text-secondary"
      >
        {showSource ? "Hide source" : "View source"}
      </button>
      {showSource && (
        <pre className="text-2xs font-mono bg-surface-code rounded p-2 overflow-x-auto whitespace-pre-wrap text-text-secondary max-h-48 overflow-y-auto">
          {html}
        </pre>
      )}
    </div>
  );
}
